import math
import random

def summarize_iid(values):
    if type(values) is not list or not 2<=len(values)<=20000:
        raise ValueError("invalid bounded iid sample")
    if any(type(x) is not float or not math.isfinite(x) or not 0.0<=x<=1e6 for x in values):
        raise ValueError("invalid payoff sample")
    n=len(values)
    mean=math.fsum(values)/n
    variance=math.fsum((x-mean)**2 for x in values)/(n-1)
    se=math.sqrt(variance/n)
    return n,mean,se,(mean-1.96*se,mean+1.96*se)

def mc_call(pairs,seed):
    # Fixed no-dividend European model S=K100,r=.05,T1,sigma=.2.
    if type(pairs) is not int or not 2<=pairs<=10000 or type(seed) is not int or not 0<=seed<=1000000:
        raise ValueError("invalid pair budget or seed")
    discount=math.exp(-0.05)
    def payoff(z):return discount*max(100.0*math.exp(0.03+0.2*z)-100.0,0.0)
    plain_rng=random.Random(seed)
    anti_rng=random.Random(seed+1)
    plain=[payoff(plain_rng.gauss(0.0,1.0)) for _ in range(2*pairs)]
    independent_pair_means=[]
    for _ in range(pairs):
        z=anti_rng.gauss(0.0,1.0)
        independent_pair_means.append((payoff(z)+payoff(-z))/2.0)
    return summarize_iid(plain),summarize_iid(independent_pair_means)

plain,anti=mc_call(2000,1729)
for name,result in (("plain",plain),("antithetic_pair",anti)):
    n,mean,se,interval=result
    print(name,n,f"mean={mean:.6f} se={se:.6f}",f"CI=({interval[0]:.6f},{interval[1]:.6f})")
print(summarize_iid([0.0,2.0])[0:3])
